/** 牌面包 @meemahjong/tiles. index.js is generated by build_index.py; this file is hand-written. */

export type NumberSuit = 'm' | 'p' | 's';
export type Suit = NumberSuit | 'z';

/** MPSZ code: 1m–9m 万, 1p–9p 饼, 1s–9s 条, 1z–7z = 东 南 西 北 白 发 中. */
export type TileCode =
  | `${1 | 2 | 3 | 4 | 5 | 6 | 7 | 8 | 9}${NumberSuit}`
  | `${1 | 2 | 3 | 4 | 5 | 6 | 7}z`;

/** Package version the faces were built for, e.g. "0.1.0". */
export const VERSION: string;

/** All 34 codes in MPSZ order (m → p → s → z). Display order is up to the app. */
export const TILE_CODES: readonly TileCode[];

export function isTileCode(s: string): s is TileCode;

/** viewBox of every SVG: 0 0 400 507. */
export const TILE_SIZE: { readonly width: 400; readonly height: 507 };

/** Face colour used inside the SVGs; replace it to recolour the tile face. */
export const FACE_COLOR: '#FDFDFB';

/** Face only: no plate, transparent background. Complete standalone <svg> strings. */
export const symbols: Readonly<Record<TileCode, string>>;

/** Face on the standard plate (rounded rect with border). Complete standalone <svg> strings. */
export const tiles: Readonly<Record<TileCode, string>>;

/**
 * On screen for players who do not read Chinese: 万 with 1–9 and the winds with
 * E S W N in the top-left corner, on the standard plate. Only those 13 tiles;
 * use `tiles` for the rest (饼 and 条 can be counted, the dragons differ in colour).
 */
export const numberedTiles: Readonly<Partial<Record<TileCode, string>>>;

/** Tile backs: complete tiles with their own plate. */
export const backs: Readonly<{ plain: string; question: string }>;
